using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityEvaluationTests : IAsyncLifetime
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    private List<GoldenCase> _goldenCases = [];
    private string _rubric = string.Empty;

    public async Task InitializeAsync()
    {
        var json = await File.ReadAllTextAsync(GoldenPath);
        _goldenCases = JsonSerializer.Deserialize<List<GoldenCase>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true }) ?? [];

        _rubric = await File.ReadAllTextAsync(RubricPath);
    }

    public Task DisposeAsync() => Task.CompletedTask;

    [Fact]
    public void GoldenCasesLoaded()
    {
        Assert.NotEmpty(_goldenCases);
    }

    [Fact]
    public void RubricLoaded()
    {
        Assert.False(string.IsNullOrWhiteSpace(_rubric));
    }

    [Fact]
    public async Task EvaluateQuality()
    {
        foreach (var golden in _goldenCases)
        {
            Assert.NotNull(golden.Id);
            Assert.NotNull(golden.UserMessage);
            Assert.NotEmpty(golden.ExpectedTraits);

            // TODO: Wire up the agent endpoint and run evaluation against the rubric.
            // For each golden case, invoke the agent with golden.UserMessage,
            // then evaluate the response against golden.ExpectedTraits using the rubric.
            await Task.CompletedTask;
        }
    }
}

public sealed class GoldenCase
{
    public string Id { get; set; } = string.Empty;
    public string UserMessage { get; set; } = string.Empty;
    public List<string> ExpectedTraits { get; set; } = [];
}

